<?php
declare(strict_types=1);
require dirname(__DIR__) . '/native/bootstrap.php';

use Kulturhus\Native\Cms\{Articles, Conflict, DataModel, Media, Pages, Schema, Templates};
use Kulturhus\Native\Shared\{Access, Db};
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Web\Articles as ArticleView;

$checks = 0;
function articleCheck(bool $ok, string $label): void { global $checks; if (!$ok) throw new RuntimeException('FAIL: ' . $label); $checks++; }
function articleReject(callable $fn, string $class, string $label): void { try { $fn(); } catch (Throwable $e) { articleCheck($e instanceof $class, $label . ' (' . $e::class . ')'); return; } throw new RuntimeException('FAIL: accepted ' . $label); }

$db = TestSupport::db();
$seeds = TestSupport::seed($db);
Schema::install($db);
$run = 'news-' . bin2hex(random_bytes(5));
$actors = [];
foreach ($seeds as $role => $id) {
    $actors[$role] = $run . '-' . $role;
    Db::run($db, 'INSERT INTO native_users(id,club_id,name) VALUES(?,?,?)', [$actors[$role], $role === 'outsider' ? $run . '-foreign' : $run, 'Synthetische Beiträge ' . $role]);
    Db::run($db, 'INSERT INTO native_grants(actor_id,module,capability) SELECT ?,module,capability FROM native_grants WHERE actor_id=?', [$actors[$role], $id]);
}
$admin = new Access($db, $actors['admin']);
$editor = new Access($db, $actors['editor']);
$reader = new Access($db, $actors['reader']);
$outsider = new Access($db, $actors['outsider']);
$articles = new Articles($db, $admin);
$editorArticles = new Articles($db, $editor);
$readArticles = new Articles($db, $reader);
$outsideArticles = new Articles($db, $outsider);
$pages = new Pages($db, $admin);
$root = dirname(__DIR__, 2) . '/.local/native-news-tests/' . $run;
mkdir($root, 0700, true);
$media = new Media($db, $admin, $root . '/media');
$source = $root . '/synthetic.png';
$image = imagecreatetruecolor(60, 40); imagefill($image, 0, 0, imagecolorallocate($image, 32, 85, 65)); imagepng($image, $source); unset($image);
$asset = $media->upload($source, 'synthetic-news.png', 'Synthetisches Bild <b>kein HTML</b>');
$secondAsset = $media->upload($source, 'second-news.png', 'Zweites synthetisches Bild');
$csrf = 'synthetic-news-csrf';
$view = new ArticleView($db, $admin, $root . '/media', $csrf);
$readerView = new ArticleView($db, $reader, $root . '/media', $csrf);
$outsideView = new ArticleView($db, $outsider, $root . '/media', $csrf);
$input = ['title' => 'Kultur & Begegnung <script>', 'slug' => 'aktuelles/gemeinsam', 'news_date' => '2026-10-07', 'excerpt' => 'Ein synthetischer Rückblick.', 'body_html' => '<p>Hallo <strong>Kultur</strong> 😀</p><script>alert(1)</script>', 'media_ids' => [$asset['id']], 'gallery_items' => [['id' => $asset['id'], 'caption' => 'Veröffentlichte Beschriftung', 'tags' => []]]];
articleCheck(isset(Templates::all()['news']), 'builtin news exists');
articleCheck((new DataModel($db, $admin))->template('news')['renderer'] === 'news', 'declarative builtin works');
articleCheck($articles->publicCount() === 0 && $articles->publicList() === [], 'empty public list');
articleCheck(str_contains($view->publicContent(), 'bald Geschichten'), 'empty state');
foreach (['', '2026-02-30', '2026-13-01', '7.10.2026', '2026-10-07<script>'] as $date) articleReject(fn () => $articles->save(array_replace($input, ['news_date' => $date])), InvalidArgumentException::class, 'reject invalid date ' . $date);
articleReject(fn () => $articles->save(array_replace($input, ['slug' => 'verein'])), InvalidArgumentException::class, 'article namespace');
articleReject(fn () => $articles->save(array_replace($input, ['slug' => 'aktuelles/a/b'])), InvalidArgumentException::class, 'single article segment');
articleReject(fn () => $articles->save(array_replace($input, ['template' => 'standard'])), InvalidArgumentException::class, 'no template spoofing');
$item = $editorArticles->save($input);
articleCheck($item['version'] === 1 && $item['template'] === 'news' && !$item['nav_visible'], 'create typed draft');
articleCheck($item['body_html'] === '<p>Hallo <strong>Kultur</strong> 😀</p>' && str_contains($item['body'], 'Kultur'), 'richtext sanitized and plain derived');
articleCheck($articles->publicArticle($item['slug']) === null && $articles->publicList() === [], 'draft absent publicly');
articleCheck(count($readArticles->list()) === 1, 'reader list');
articleReject(fn () => $readArticles->save($input), DomainException::class, 'reader cannot write');
articleReject(fn () => $editorArticles->publish($item['id'], 1), DomainException::class, 'editor cannot publish');
articleReject(fn () => $outsideArticles->get($item['id']), RuntimeException::class, 'cross club read denied');
articleReject(fn () => $outsideArticles->save(array_replace($input, ['id' => $item['id']]), 1), RuntimeException::class, 'cross club edit denied');
$standard = $pages->save(['title' => 'Normale Seite', 'slug' => 'normal']);
articleReject(fn () => $articles->get($standard['id']), DomainException::class, 'normal pages excluded from workflow');
articleReject(fn () => $articles->publish($standard['id'], 1), DomainException::class, 'cannot publish another type through news');
$generation = $pages->generation();
$item = $articles->publish($item['id'], 1);
articleCheck($item['version'] === 2 && $pages->generation() === $generation + 1, 'publish version and invalidation');
articleCheck($articles->publicCount() === 1 && count($articles->publicList()) === 1, 'published list and count');
articleCheck($outsideArticles->publicCount() === 0 && $outsideArticles->publicArticle($item['slug']) === null, 'cross club public data excluded');
articleCheck($media->publicVariant($asset['id'], 'medium') !== null, 'published image accessible');
$published = $articles->publicArticle($item['slug']);
$item = $editorArticles->save(['id' => $item['id'], 'title' => 'Geheimer neuer Entwurf', 'slug' => 'aktuelles/geheim', 'news_date' => '2030-01-01', 'body_html' => '<p>Entwurf geheim</p>', 'media_ids' => [$secondAsset['id']]], 2);
articleCheck($pages->generation() === $generation + 1, 'draft does not invalidate published generation');
$public = $articles->publicList()[0];
articleCheck($public['title'] === $input['title'] && $public['news_date'] === '2026-10-07' && $public['slug'] === 'aktuelles/gemeinsam', 'public title date and slug isolated');
articleCheck($public['body_html'] === $published['body_html'] && $public['media_ids'] === [$asset['id']], 'body and media snapshot isolated');
articleCheck($articles->publicArticle('aktuelles/geheim') === null, 'draft slug unavailable');
articleCheck($media->publicVariant($secondAsset['id'], 'medium') === null, 'draft image unavailable');
$html = $view->publicContent();
articleCheck(str_contains($html, 'Kultur &amp; Begegnung &lt;script&gt;') && !str_contains($html, 'Geheimer'), 'list escaping and draft isolation');
articleCheck(str_contains($html, 'datetime="2026-10-07"') && str_contains($html, '/site/aktuelles/gemeinsam'), 'semantic date and canonical article link');
$articleHtml = $view->publicContent($published);
articleCheck(str_contains($articleHtml, '<strong>Kultur</strong>') && !str_contains($articleHtml, '<script>'), 'article formatting safe');
articleCheck(str_contains($articleHtml, 'Veröffentlichte Beschriftung') && str_contains($articleHtml, 'Alle Beiträge'), 'snapshot caption and back link');
articleCheck(!str_contains($view->publicContent($item), 'Entwurf geheim'), 'view does not render supplied draft');
articleCheck(str_contains($view->latest(2), 'Was uns bewegt') && !str_contains($view->latest(2), 'Geheimer'), 'homepage section uses public data');
articleReject(fn () => $articles->save(['id' => $item['id'], 'title' => 'Stale'], 2), Conflict::class, 'stale write rejected');
articleReject(fn () => $articles->publish($item['id'], 2), Conflict::class, 'stale publish rejected');
$restored = $articles->restore($item['id'], 1, $item['version']);
articleCheck($restored['version'] === 4 && $restored['title'] === $input['title'] && $restored['news_date'] === '2026-10-07', 'restore makes fresh draft');
articleCheck($articles->publicArticle('aktuelles/gemeinsam')['version'] === 2, 'restore does not republish');
$item = $articles->publish($restored['id'], $restored['version']);
articleCheck($item['version'] === 5 && count($articles->revisions($item['id'])) === 5, 'history includes all actions');
$off = $articles->unpublish($item['id'], $item['version']);
articleCheck($articles->publicCount() === 0 && $media->publicVariant($asset['id'], 'medium') === null, 'unpublish removes list and media access');
$item = $articles->publish($off['id'], $off['version']);
for ($n = 0; $n < 13; $n++) { $p = $articles->save(['title' => 'Synthetisch ' . $n, 'slug' => 'aktuelles/folge-' . str_pad((string) $n, 2, '0', STR_PAD_LEFT), 'news_date' => $n < 2 ? '2026-10-08' : '2026-10-06']); $articles->publish($p['id'], $p['version']); }
$public = $articles->publicList(2);
articleCheck(array_column($public, 'slug') === ['aktuelles/folge-00', 'aktuelles/folge-01'], 'date descending and deterministic tie break');
articleCheck($articles->publicList(1, 2)[0]['id'] === $item['id'], 'pagination offset');
articleCheck(count($articles->publicList(12)) === 12 && count($articles->publicList(12, 12)) === 2, 'pagination bounds');
articleCheck(str_contains($view->publicContent(null, 1), 'Ältere Beiträge') && str_contains($view->publicContent(null, 2), 'Neuere Beiträge'), 'public pagination links');
articleCheck(str_contains($view->publicContent(null, 3), 'Zur ersten Seite'), 'empty page fallback');
foreach ([[0, 0], [101, 0], [1, -1], [1, 1000001]] as [$limit, $offset]) articleReject(fn () => $articles->publicList($limit, $offset), InvalidArgumentException::class, 'list bounds');
articleReject(fn () => $view->publicContent(null, 0), InvalidArgumentException::class, 'view bounds');
$beforeNew=count($pages->list());$newForm=$view->manager('new');
articleCheck(str_contains($newForm,'name="operation" value="article-save"')&&str_contains($newForm,'name="version" value="0"')&&str_contains($newForm,'name="title"')&&count($pages->list())===$beforeNew,'new article opens an unsaved editor with current fields and no original lookup');
$form = $view->manager($item['id']);
articleCheck(str_contains($form, 'data-kh-richtext') && str_contains($form, 'name="news_date"'), 'editor contains richtext and date');
articleCheck(str_contains($form, 'name="version" value="7"') && str_contains($form, 'article-restore'), 'editor uses optimistic version and restore');
articleCheck(str_contains($form, 'Beitrag veröffentlichen') && str_contains($form, 'Beitrag offline nehmen'), 'publisher controls');
articleCheck(str_contains($form, 'Synthetisches Bild &lt;b&gt;kein HTML&lt;/b&gt;'), 'media choices escape labels');
$readerDocument=new DOMDocument();$previous=libxml_use_internal_errors(true);$readerDocument->loadHTML('<?xml encoding="UTF-8">'.$readerView->manager($item['id']));libxml_clear_errors();libxml_use_internal_errors($previous);
articleCheck((new DOMXPath($readerDocument))->query('//form[translate(@method,"POST","post")="post"]')->length===0 && !str_contains($readerView->manager(), 'Neuer Beitrag'), 'reader UI has no mutation forms while retaining ordinary search filters');
articleReject(fn () => $readerView->manager('new'), DomainException::class, 'reader new screen denied');
articleReject(fn () => $outsideView->manager($item['id']), RuntimeException::class, 'cross club editor denied');
$post = ['operation' => 'article-save', 'csrf' => $csrf, 'id' => '', 'version' => '0', 'title' => 'Formularbeitrag', 'slug' => 'formular', 'news_date' => '2026-10-08', 'excerpt' => 'Formulartest', 'body_html' => '<p>Formular 😀</p>', 'cover_id' => $asset['id'], 'media_ids' => [$secondAsset['id']]];
articleReject(fn () => $view->action(array_replace($post, ['csrf' => 'wrong'])), DomainException::class, 'csrf denial');
articleReject(fn () => $readerView->action($post), DomainException::class, 'reader action denied');
articleReject(fn () => $view->action(array_replace($post, ['title' => ['bad']])), InvalidArgumentException::class, 'array field denied');
articleReject(fn () => $view->action(array_replace($post, ['version' => '-1'])), InvalidArgumentException::class, 'negative version denied');
articleReject(fn () => $view->action(array_replace($post, ['operation' => 'unknown'])), DomainException::class, 'unknown operation denied');
$createdId = $view->action($post); $created = $articles->get($createdId);
articleCheck($created['slug'] === 'aktuelles/formular' && $created['media_ids'] === [$asset['id'], $secondAsset['id']], 'HTTP create and cover ordering');
$post['id'] = $createdId; $post['version'] = '1'; $post['body_html'] = '';
$view->action($post); $created = $articles->get($createdId);
articleCheck($created['body_html'] === '' && $created['body'] === '', 'HTTP empty editor clears text');
$action = ['csrf' => $csrf, 'id' => $createdId, 'version' => '2', 'operation' => 'article-publish'];
$view->action($action);
articleCheck($articles->publicArticle('aktuelles/formular') !== null, 'HTTP publish');
$action['operation'] = 'article-upload'; $action['version'] = '3';
articleReject(fn () => $view->action($action, ['image' => ['error' => UPLOAD_ERR_OK, 'tmp_name' => $source, 'name' => 'forged.png']]), DomainException::class, 'HTTP upload rejects server path');
$action['operation'] = 'article-restore'; $action['revision'] = '1'; $view->action($action);
articleCheck(str_contains($articles->get($createdId)['body_html'], 'Formular'), 'HTTP restore');
$action['operation'] = 'article-unpublish'; $action['version'] = '4'; $view->action($action);
articleCheck($articles->publicArticle('aktuelles/formular') === null, 'HTTP offline');
$foreignMedia = new Media($db, $outsider, $root . '/media'); $foreign = $foreignMedia->upload($source, 'foreign.png', 'Fremdes synthetisches Bild');
articleReject(fn () => $articles->save(array_replace($input, ['slug' => 'aktuelles/fremdes-bild', 'media_ids' => [$foreign['id']]])), InvalidArgumentException::class, 'cross club image denied');
$plain = $articles->save(['id' => $createdId, 'body' => 'Nur Klartext'], 5);
articleCheck($plain['body_html'] === '' && $plain['body'] === 'Nur Klartext', 'plain partial update replaces rich body');
articleCheck(str_contains($view->manager(), 'Formularbeitrag') && str_contains($view->manager(), 'Entwurf / offline'), 'manager list reflects offline state');
$doc = new DOMDocument(); libxml_use_internal_errors(true); $doc->loadHTML('<?xml encoding="UTF-8">' . $view->manager($item['id'])); libxml_clear_errors();
articleCheck((new DOMXPath($doc))->query('//form//form')->length === 0, 'no nested forms');
$beforeLive=$articles->get($createdId);
$liveDoc=new DOMDocument();$liveDoc->loadHTML('<?xml encoding="UTF-8">'.$view->manager($createdId));$liveQuery=new DOMXPath($liveDoc);
articleCheck($liveQuery->query('//*[@data-page-live]//iframe[@sandbox="allow-same-origin"]')->length===1,'article uses passive same-origin actual website live preview');
articleCheck($liveQuery->query('//form[.//input[@name="operation" and @value="article-save"]]//input[@name="title"]')->length===1,'live preview retains exactly one original article title and save form');
articleCheck(str_contains($liveQuery->query('//*[@data-page-live-html]')->item(0)->textContent,'Nur Klartext'),'live preview renders exact current unsaved publication draft in website layout');
articleCheck($articles->get($createdId)===$beforeLive,'reading live preview does not create a revision or publication');
echo json_encode(['suite' => 'native-articles', 'passed' => $checks], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) . PHP_EOL;
